import { useState } from "react";
import styles from './SudokuBoard.module.css'

function SudokuBoard() {
  const { initialBoard, solution, showSolution, onCellChange } = props;
  const [board, setBoard] = useState(initialBoard);

  const onCellChanged = (index, value) => {
    setBoard(board.map((cell, i) => i === index ? value : cell));
  };

  const renderCells = () => board.map((cell, i) => (
    <div className={styles.cell}>
      <input
        type="text"
        pattern="\d*"
        novalidate=""
        id={`input-${i}`}
        value={showSolution ? solution[i] : cell}
        maxlength="1"
        onChange={() => onCellChange(i, cell)}
      />
    </div>
  ));

  return (
    <div className={styles.board}>
     {renderCells()}
    </div>
  )
}

export default SudokuBoard;
